using System;using System.Linq;using System.IO;using System.IO.Pipes;using System.Text;using System.Threading.Tasks;using System.Drawing;using System.Windows.Forms;using System.Security.Cryptography;using System.Security.Principal;
static class CaptureInboxTransport {
 internal static string Pipe{get{using(var sha=SHA256.Create())return "JagoLibraryCaptureInbox."+WindowsIdentity.GetCurrent().User.Value.Replace('-','_')+"."+BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(JagoSuiteBootstrap.Root))).Replace("-","").Substring(0,12);}}
 internal static bool Forward(string folder){try{using(var pipe=new NamedPipeClientStream(".",Pipe,PipeDirection.Out)){pipe.Connect(1000);using(var writer=new StreamWriter(pipe,new UTF8Encoding(false)))writer.WriteLine(folder);}return true;}catch{return false;}}
}
sealed partial class WorldWindow {
 NamedPipeServerStream captureInboxListener;
 void StartCaptureInbox(){FormClosed+=(s,e)=>{if(captureInboxListener!=null)captureInboxListener.Dispose();};Task.Run(()=>{while(!closing){try{using(var server=new NamedPipeServerStream(CaptureInboxTransport.Pipe,PipeDirection.In,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous)){captureInboxListener=server;server.WaitForConnection();using(var reader=new StreamReader(server)){string folder=reader.ReadLine();if(folder==null||folder.Length>4000||!Path.IsPathRooted(folder)||!Directory.Exists(folder))continue;BeginInvoke((Action)(()=>CaptureInboxReceived(folder)));}}}catch{if(closing)return;System.Threading.Thread.Sleep(200);}}});}
 async void CaptureInboxReceived(string folder){try{for(int i=0;i<100;i++){if(ready&&await browser.CoreWebView2.ExecuteScriptAsync("!!window.appReady")=="true")break;await Task.Delay(100);}ManagedPost(new{type="companion-capture-inbox",path=Path.GetFullPath(folder)});string owner=Environment.GetEnvironmentVariable("JAGO_WORKSPACE_ROOT"),tab=Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TAB_ID");if(owner!=null&&tab!=null){var json=new System.Web.Script.Serialization.JavaScriptSerializer();File.WriteAllText(Path.Combine(owner,"action-"+Guid.NewGuid()+".json"),json.Serialize(new{action="focus",id=tab}));}else{if(WindowState==FormWindowState.Minimized)WindowState=FormWindowState.Normal;Show();Activate();}}catch(Exception ex){ManagedPost(new{type="error",message="Capture inbox: "+ex.Message});}}
}
